function waveQueue(stage){
  // These three introductions use authored waves; later chapters retain the original generator.
  if(stage.number===1)return [1,2.6,6.2,7.8].map(at=>({kind:'y',at}));
  if(stage.number===2)return [1,2.4,3.8,11.2,12.6,14].map(at=>({kind:'y',at}));
  if(stage.number===3)return ['y','y','g','y','y'].map((kind,i)=>({kind,at:[1,3,7.5,9.5,14][i]}));
  const order=Object.entries(stage.composition).flatMap(([kind,n])=>Array(n).fill(kind));const queue=[];let time=1;while(order.length){for(let i=0;i<stage.groupSize&&order.length;i++){const index=i%2===0?0:Math.floor(order.length/2);queue.push({kind:order.splice(index,1)[0],at:time});time+=stage.interval}time+=stage.groupGap}
  // Chapter 12 alone: scale every inter-spawn gap (including group breaks) by 1.2.
  if(stage.number===12)return queue.map(({kind,at})=>({kind,at:1+(at-1)*1.2}));
  return stage.number===14?queue.map(({kind,at})=>({kind,at:1+(at-1)*1.3})):queue}
