const $=id=>document.getElementById(id),xy=p=>[p%W,Math.floor(p/W)],valid=(p)=>p>=0&&p<W*H;
const near=p=>{let [x,y]=xy(p);return [[x,y-1],[x+1,y],[x,y+1],[x-1,y]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H).map(([a,b])=>b*W+a)};
function initial(){
  let tiles=Array(W*H).fill('wall');
  // Keep only small building pads and short gate approaches; the player digs the route.
  for(const [x,y] of [[3,2],[9,7],[14,2]])for(let dy=0;dy<3;dy++)for(let dx=0;dx<3;dx++)tiles[(y+dy)*W+x+dx]='floor';
  for(const [x,y] of [[2,5],[3,5],[16,6],[17,6]])tiles[y*W+x]='floor';
  // Permanent rock forces a choice of winding approaches, but does not seal the map.
  for(const [x,y] of [[7,2],[7,3],[7,4],[8,4],[8,5],[12,1],[12,2],[12,3],[13,4],[13,5],[14,7],[14,8],[9,1],[10,1],[10,10],[11,10]])tiles[y*W+x]='bedrock';
  for(let y=5;y<7;y++){for(let x=0;x<2;x++)tiles[y*W+x]='entry';for(let x=W-2;x<W;x++)tiles[y*W+x]='office'}
  return {tiles,rooms:[],units:[],equip:{},money:150,wave:0,phase:'build',progress:0,queue:[],enemies:[],time:0,spawnAt:0,spawned:0,kills:0,earned:0,fallen:new Set(),alarm:0,events:[],nextId:1,paused:false,speed:1,signals:[],fx:[],result:'',rewardedStages:[],totalKills:0,totalDefenses:0};
}
const clone=v=>structuredClone(v);

// Autosave is opt-in after title selection; merely opening the game never writes progress.
let sessionActive=false,restoringSession=false,lastAutosaveAt=0,lastSaveGate='',lastSaveBody='',saveFailed=false;
const sessionStorageAPI=()=>typeof localStorage==='undefined'?null:localStorage;
function storySession(){return typeof StoryUI!=='undefined'?StoryUI.snapshot?.()||null:null}
function captureSession(){return {version:1,state:S,checkpoint,battleSnapshot,lastReport,comparisonPrevious,reportHistory,mode,activeTab,showRoute,selected,selectedResident,pendingSign,acc,presentation:storySession()}}
function autosave(force=false){
 if(!sessionActive||restoringSession||typeof WakeariAutosave==='undefined')return false;
 const presentation=storySession(),gate=[S.phase,S.wave,S.paused,S.speed,presentation?.kind,presentation?.index].join(':');
 const now=Date.now();if(!force&&S.phase==='battle'&&gate===lastSaveGate&&now-lastAutosaveAt<1000)return true;
 const body=WakeariAutosave.encode(captureSession());if(body===lastSaveBody&&!saveFailed)return true;
 const ok=WakeariAutosave.write(sessionStorageAPI(),{...captureSession(),savedAt:new Date().toISOString()});
 saveFailed=!ok;if(ok){lastSaveBody=body;lastAutosaveAt=now;lastSaveGate=gate}
 const status=$('autosaveStatus');if(status){status.textContent=ok?'自動保存済み':'自動保存できません。空き容量やブラウザの設定をご確認ください';status.classList.toggle('save-error',!ok)}
 return ok;
}
function showGameTitle(){
 autosave(true);sessionActive=false;bgm('title');
 if(typeof StoryUI!=='undefined')StoryUI.close();
 const store=sessionStorageAPI(),saved=typeof WakeariAutosave!=='undefined'?WakeariAutosave.read(store):null;
 showModal('立ち退きません！',`<div class="wake-title"><p class="wake-title-sub">～地下のわけあり荘～</p><p>ここは、みんなの帰る場所。<br>今日も地下の暮らしを守ろう。</p></div>`,[['はじめから',requestNewGame],['つづきから',continueGame]]);
 $('modal').classList.add('wake-title-screen');
 const buttons=$('modalActions').querySelectorAll('button');if(buttons[1])buttons[1].disabled=!saved;
 const shell=document.querySelector?.('.app-shell');if(shell){shell.inert=true;shell.setAttribute('aria-hidden','true')}
 buttons[0]?.focus();
}
function requestNewGame(){
 if(typeof WakeariAutosave!=='undefined'&&WakeariAutosave.hasStored(sessionStorageAPI())){
  showModal('はじめから始めますか？','<p>現在のゲーム進行の自動保存を、新しい進行で上書きします。</p><p>「物語を振り返る」の解放記録は残ります。</p>',[['上書きしてはじめる',beginNewGame],['やめる',showGameTitle]]);
  return;
 }
 beginNewGame();
}
function beginNewGame(){
 restoringSession=true;S=initial();checkpoint=clone(S);battleSnapshot=null;lastReport=null;comparisonPrevious=null;reportHistory=[];
 mode='dig';activeTab='dig';showRoute=false;selected=null;selectedResident=null;pendingSign=null;acc=0;last=0;lastSaveBody='';lastSaveGate='';
 hideModal();sessionActive=true;restoringSession=false;renderTools();render();autosave(true);bgm('build');
 if(typeof StoryUI!=='undefined')StoryUI.showChapter(0);else showTutorial();
}
function continueGame(){
 const data=typeof WakeariAutosave!=='undefined'?WakeariAutosave.read(sessionStorageAPI()):null;
 if(!data){showGameTitle();return false}
 restoringSession=true;S=data.state;checkpoint=data.checkpoint||clone(S);battleSnapshot=data.battleSnapshot||null;
 lastReport=data.lastReport||null;comparisonPrevious=data.comparisonPrevious||null;reportHistory=Array.isArray(data.reportHistory)?data.reportHistory:[];
 mode=data.mode||'dig';activeTab=['dig','home','trap'].includes(data.activeTab)?data.activeTab:'dig';showRoute=!!data.showRoute;
 selected=data.selected??null;selectedResident=data.selectedResident??null;pendingSign=data.pendingSign||null;acc=Number.isFinite(data.acc)?Math.max(0,Math.min(.1,data.acc)):0;last=0;
 hideModal();sessionActive=true;renderTools();render();
 bgm(S.phase==='battle'?'battle':S.phase==='build'?'build':'none');if(S.phase==='battle')bgmPause(!!S.paused);
 if(data.presentation&&typeof StoryUI!=='undefined')StoryUI.restore(data.presentation,showGameTitle);
 else if(S.phase==='result')showResult();
 restoringSession=false;lastSaveBody='';autosave(true);return true;
}

function message(s){$('toast').textContent=s;S.events.unshift(s);S.events=S.events.slice(0,28);$('log').innerHTML=S.events.map(v=>`<div>${escapeHtml(v)}</div>`).join('');const line=eventDialogue(s);if(line)moguruSay(line)}
function eventDialogue(s){if(/掘削済み|掘削できません|隣接する壁だけ/.test(s))return 'ここは掘れないみたいです……';if(s.includes('新しい部屋を登録'))return 'これで新しい部屋ができました！';if(s.includes('が入居しました'))return 'どうぞ、よろしくお願いします！';if(s.includes('満腹…Zzz'))return 'えっ、こんなときに寝るんですか！？';if(s.includes('ひえー！'))return 'ひゃっ！ また誰か来たんですか！？';if(s.includes('うるさーい！'))return 'お、起きたー！！';return null}
const BASE_DIALOGUE='今日から僕が大家さん……大丈夫かなぁ';
function fitMoguruSpeech(line){
  // Presentation-only: keep speech to two balanced lines without blank rows.
  if(!line.style||typeof line.style.setProperty!=='function')return;
  for(let size=18;size>=13;size--){
    line.style.setProperty('font-size',`${size}px`,'important');
    if(!Number.isFinite(line.scrollHeight)||line.scrollHeight<=size*1.25*2+2)break;
  }
}
function moguruSay(s){let line=$('moguruSpeech');if(!line)return;if(dialogueText!==s){line.textContent=s;dialogueText=s;fitMoguruSpeech(line)}dialogueUntil=Date.now()+4600}
function refreshDialogue(){const fallback=STAGE_DATA[S.wave]?.warning||BASE_DIALOGUE;if(S.phase==='result'||Date.now()<dialogueUntil||dialogueText===fallback)return;let line=$('moguruSpeech');if(line)line.textContent=fallback;dialogueText=fallback}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function initStats(){
  S.stats={residents:{},equipment:{},enemies:{},serial:Object.fromEntries(Object.keys(ENEMIES).map(k=>[k,0])),firstArrival:null};
  for(const u of S.units)S.stats.residents[u.id]={id:u.id,kind:u.kind,name:TYPES[u.kind].name,room:u.room,dealt:0,normalDamage:0,specialDamage:0,poisonDamage:0,poisonKills:0,poisonApplications:0,screams:0,screamHits:0,screamDamage:0,enhancedDamage:0,lureAttempts:0,lureSuccess:0,lureFailures:0,lureKinds:{},lureExtraSteps:0,lureDamage:0,lureAttacks:0,lureCombos:0,taken:0,kills:0,attacks:0,fallen:false,naps:0,alarms:0,alarmTargets:0,alarmBonus:0,alarmActiveSeconds:0,alarmBlocked:{cooldown:0,outside:0},wakes:0,areaHits:0,repairs:0,repairIds:[],repairInterrupts:0,enhances:0,enhancedTriggers:0,showoffs:0,showoffDamage:0,combos:0,comboDamage:0,spores:0,sporeTiles:0,sporeHits:0,slowedIds:[],patrolSteps:0,naturalHeals:0,naturalHealedHp:0,restSeconds:0,restStops:0};
  for(const [p,e] of Object.entries(S.equip))S.stats.equipment[p]={pos:Number(p),kind:e.kind,uses:0,hits:0,affectedIds:[],dealt:0,spikeNormalDamage:0,spikeGondaBonus:0,kills:0,specialTriggers:0,disarms:0,awakened:0,slowedIds:[],redirects:0,extraSteps:0,stoppedTime:0,pushedIds:[],heals:0,healedIds:[],healedHp:0,enhancedHeals:0,destroyed:0,repaired:0,depleted:false};
}
function residentStat(u){return S.stats?.residents[u?.id]}
function enemyStat(e){return S.stats?.enemies[e?.id]}
function equipStat(p){return S.stats?.equipment[p]}
function recordDeviceImpact(p,target){const st=equipStat(p);if(!st)return;st.hits++;if(target&&!st.affectedIds.includes(target.id))st.affectedIds.push(target.id)}
function markArrival(e){let a=enemyStat(e);if(a&&!a.reachedAt&&a.reachedAt!==0){a.reachedAt=S.time;if(!S.stats.firstArrival){S.stats.firstArrival={name:a.name,time:S.time};sfx('office_alert')}}}
function makeReport(won){
  const s=S.stats||{residents:{},equipment:{},enemies:{},firstArrival:null};
  const residents=Object.values(s.residents).map(v=>({...v})),equipment=Object.values(s.equipment).map(v=>({...v})),enemies=Object.values(s.enemies).map(v=>({...v}));
  return {wave:S.wave,won,kills:S.kills,spawned:S.spawned,time:S.time,progress:S.progress,earned:S.earned,bonus:S.bonusEarned||0,
    steps:enemies.reduce((n,e)=>n+e.steps,0),firstArrival:s.firstArrival?{...s.firstArrival}:null,
    residentDamage:residents.reduce((n,r)=>n+r.dealt,0),trapDamage:equipment.reduce((n,e)=>n+e.dealt,0),residents,equipment,enemies};
}
function compactComparison(r){return r?{wave:r.wave,won:r.won,kills:r.kills,time:r.time,progress:r.progress,residentDamage:r.residentDamage,trapDamage:r.trapDamage,firstArrival:r.firstArrival?{...r.firstArrival}:null}:null}
const fmt=n=>Number(n).toFixed(1).replace(/\.0$/,'');
function comparisonHtml(a,b){if(!b||a.wave!==b.wave)return '';
  const rows=[['勝敗',a.won?'成功':'失敗',b.won?'成功':'失敗',null],['撃退数',a.kills,b.kills,a.kills-b.kills],['戦闘時間（秒）',fmt(a.time),fmt(b.time),a.time-b.time],['管理室ゲージ（%）',fmt(a.progress),fmt(b.progress),a.progress-b.progress],['住人与ダメージ',a.residentDamage,b.residentDamage,a.residentDamage-b.residentDamage],['罠与ダメージ',a.trapDamage,b.trapDamage,a.trapDamage-b.trapDamage],['最初の到達（秒）',a.firstArrival?fmt(a.firstArrival.time):'未到達',b.firstArrival?fmt(b.firstArrival.time):'未到達',a.firstArrival&&b.firstArrival?a.firstArrival.time-b.firstArrival.time:null]];
  return `<h3>前回の同じ侵攻との比較</h3><table class="report-table"><tr><th>項目</th><th>今回</th><th>前回</th><th>差分</th></tr>${rows.map(([n,v,p,d])=>`<tr><td>${n}</td><td>${v}</td><td>${p}</td><td>${d===null?'—':`${d>=0?'+':'−'}${fmt(Math.abs(d))}`}</td></tr>`).join('')}</table><p class="micro-note">差分は今回−前回です。増減が必ずしも改善を意味するわけではありません。</p>`;
}
function analysisHtml(r){if(!r)return '<p>まだ戦闘記録はありません。</p>';
  const groups=Object.values(r.enemies.reduce((acc,e)=>{const g=acc[e.kind]??={kind:e.kind,name:ENEMIES[e.kind].name,count:0,kills:0,taken:0,disarms:0,destroyed:0,buffs:0,reward:0,arrived:0,work:0};g.count++;g.kills+=Number(e.defeated);g.taken+=e.taken;g.disarms+=e.disarms;g.destroyed+=e.destroyed||0;g.buffs+=e.buffs||0;g.reward+=e.reward||0;g.arrived+=Number(e.reachedAt!=null);g.work+=e.workTime;return acc},{}));
  const summary=`<h3>敵の種類別集計</h3><table class="report-table"><tr><th>種類</th><th>出現/撃退</th><th>被ダメ</th><th>解除/破壊</th><th>支援</th><th>到達/作業</th><th>報酬</th></tr>${groups.map(g=>`<tr><td>${g.name}</td><td>${g.count}/${g.kills}</td><td>${g.taken}</td><td>${g.disarms}/${g.destroyed}</td><td>${g.buffs}</td><td>${g.arrived}/${fmt(g.work)}秒</td><td>${g.reward}</td></tr>`).join('')}</table>`;
  const rs=r.residents.map(u=>`<tr><td>${u.name} #${u.id}</td><td>${fmt(u.dealt)}<small>通常${fmt(u.normalDamage||0)}／特殊${fmt(u.specialDamage||0)}／連携${fmt(u.comboDamage||0)}／毒${fmt(u.poisonDamage||0)}</small></td><td>${u.taken}</td><td>${u.kills}</td><td>${u.attacks}</td><td>${u.fallen?'戦闘不能':'生存'}</td><td>${u.kind==='pak'?`昼寝${u.naps}`:u.kind==='bibi'?`警報${u.alarms}回／強化対象${u.alarmTargets}人／悲鳴${u.screams}回・命中${u.screamHits}・${fmt(u.screamDamage)}ダメ／支援追加${fmt(u.alarmBonus)}`:u.kind==='dos'?`覚醒${u.wakes}／範囲命中${u.areaHits}`:u.kind==='pika'?`修理${u.repairs}件／中断${u.repairInterrupts}／設備強化${u.enhances}回／強化発動${u.enhancedTriggers}回／追加${fmt(u.enhancedDamage)}ダメ`:u.kind==='mie'?`見栄${u.showoffs}回／連携${u.combos}回・${u.comboDamage}ダメ／誘導${u.lureAttempts}回・成功${u.lureSuccess}・失敗${u.lureFailures}／対象${Object.entries(u.lureKinds||{}).map(([k,n])=>`${ENEMIES[k]?.name||k}${n}`).join('、')||'なし'}／遠回り${u.lureExtraSteps}マス／誘導${fmt(u.lureDamage)}ダメ／誘導中攻撃${u.lureAttacks}回・連携${u.lureCombos}回`:`胞子設置${u.sporeTiles}マス／命中${u.sporeHits}回／毒付与${u.poisonApplications}回・${fmt(u.poisonDamage)}ダメ・撃退${u.poisonKills}／減速${u.slowedIds.length}人`}</td></tr>`).join('');
  const es=r.equipment.map(e=>`<tr><td>${EQUIPMENT[e.kind]?.name||e.kind} (${xy(e.pos)[0]+1},${xy(e.pos)[1]+1})</td><td>${e.uses}</td><td>${e.hits||0}</td><td>${e.affectedIds?.length||0}</td><td>${fmt(e.dealt)}<small>撃退${e.kills||0}</small></td><td>${e.disarms}</td><td>特殊効果${e.specialTriggers||0}回／${e.kind==='noise'?`覚醒${e.awakened}`:e.kind==='sticky'?`減速${e.slowedIds?.length||0}人`:e.kind==='fake_sign'?`誘導${e.redirects}回／追加${e.extraSteps}歩`:e.kind==='pitfall'?`足止め${fmt(e.stoppedTime)}秒`:e.kind==='haunted_tv'?`後退${e.pushedIds?.length||0}人`:'—'}</td></tr>`).join('');
  const ws=r.enemies.map(e=>`<tr><td>${e.name}</td><td>${e.taken}</td><td>${e.defeated?'撃退':e.reachedAt!==null?'管理室到達':'侵攻中断'}</td><td>${fmt(e.workTime)}秒</td><td>${e.disarms}/${e.destroyed||0}</td><td>${e.buffs||0}</td><td>+${e.reward||0}</td></tr>`).join('');
  const bibi=r.residents.filter(u=>u.kind==='bibi').map(u=>`警報${u.alarms}回・対象${u.alarmTargets}人・支援実時間${fmt(u.alarmActiveSeconds||0)}人秒・追加${fmt(u.alarmBonus)}ダメ・不発理由（再発動待ち${u.alarmBlocked?.cooldown||0}回／範囲外${u.alarmBlocked?.outside||0}回）`).join('／')||'配置なし';
  return `<div class="analysis-scroll"><h3>第${r.wave+1}回：${r.won?'防衛成功':'防衛失敗'}</h3><p>侵入 ${r.spawned}人／撃退 ${r.kills}人／戦闘 ${fmt(r.time)}秒<br>最終作業ゲージ ${fmt(r.progress)}%／獲得管理費 ${r.earned}（防衛報酬 ${r.bonus}）<br>最初の管理室到達：${r.firstArrival?`${r.firstArrival.name}・${fmt(r.firstArrival.time)}秒`:'なし'}</p><p>ビビリーヌ分析：${bibi}<br>設備未発動：${r.equipment.filter(e=>e.uses===0).length}個</p>${comparisonHtml(r,r.previous)}${summary}<details><summary>個体別詳細（${r.enemies.length}体）</summary><h3>住人別</h3><table class="report-table"><tr><th>住人</th><th>与</th><th>被</th><th>撃退</th><th>攻撃</th><th>状態</th><th>習性</th></tr>${rs||'<tr><td colspan="7">住人なし</td></tr>'}</table><h3>設備別</h3><table class="report-table"><tr><th>設備</th><th>発動</th><th>命中</th><th>影響人数</th><th>与</th><th>解除</th><th>効果</th></tr>${es||'<tr><td colspan="7">設備なし</td></tr>'}</table><h3>業者別</h3><table class="report-table"><tr><th>業者</th><th>被</th><th>状態</th><th>作業</th><th>解除/破壊</th><th>支援</th><th>報酬</th></tr>${ws||'<tr><td colspan="7">出現なし</td></tr>'}</table></details></div>`;
}
function lunchboxAnalysisHtml(r){const items=r.equipment.filter(e=>e.kind==='lunchbox');const total=key=>items.reduce((sum,e)=>sum+(e[key]||0),0);const people=new Set(items.flatMap(e=>e.healedIds||[]));return `<div class="analysis-scroll"><h3>大家さんの差し入れ箱</h3><p>設置${items.length}個／発動${total('heals')}回／回復した住人${people.size}人／回復HP合計${fmt(total('healedHp'))}<br>強化中の回復${total('enhancedHeals')}回／破壊${total('destroyed')}回／修理${total('repaired')}回／使い切り${items.filter(e=>e.depleted).length}個</p></div>`}
function spikeAnalysisHtml(r){const items=r.equipment.filter(e=>e.kind==='spike'),sum=key=>items.reduce((n,e)=>n+(e[key]||0),0);return `<div class="analysis-scroll"><h3>トゲ罠の内訳</h3><p>通常ダメージ ${fmt(sum('spikeNormalDamage'))}／権田への追加ダメージ ${fmt(sum('spikeGondaBonus'))}／合計 ${fmt(sum('dealt'))}<br>発動 ${sum('uses')}回／解除 ${sum('disarms')}回／破壊 ${sum('destroyed')}回</p></div>`}
function newAbilityAnalysisHtml(r){const gen=r.enemies.filter(e=>e.kind==='g'),gonda=r.enemies.filter(e=>e.kind==='d'),sum=(items,key)=>items.reduce((n,v)=>n+(v[key]||0),0);return `<div class="analysis-scroll"><h3>ゲンの罠回避</h3><p>見抜いた罠 ${sum(gen,'seenTraps')}個／安全な迂回 ${sum(gen,'detours')}回／効果を受けず通過 ${sum(gen,'immunePasses')}回／追加移動距離 ${sum(gen,'detourExtra')}マス</p><h3>権田のトゲ罠</h3><p>踏んだ数 ${sum(gonda,'gondaSpikeSteps')}／通常被ダメージ ${fmt(sum(gonda,'gondaSpikeNormal'))}／特効被ダメージ ${fmt(sum(gonda,'gondaSpikeBonus'))}／踏んだ後の破壊 ${sum(gonda,'gondaSpikeBreaks')}回</p><h3>住人の自然回復</h3><table class="report-table"><tr><th>住人</th><th>回復HP/回数</th><th>休息時間</th><th>中断</th></tr>${r.residents.map(u=>`<tr><td>${u.name}</td><td>${fmt(u.naturalHealedHp||0)} / ${u.naturalHeals||0}</td><td>${fmt(u.restSeconds||0)}秒</td><td>${u.restStops||0}回</td></tr>`).join('')}</table></div>`}
function showAnalysis(r){if(!r)return;showModal('📊 戦闘分析',analysisHtml(r)+lunchboxAnalysisHtml(r)+spikeAnalysisHtml(r)+newAbilityAnalysisHtml(r),[['閉じる',()=>{hideModal();if(S.phase==='result')showResult()}]])}
const walkable=t=>t==='floor'||t==='entry'||t==='office';
function bfs(from,to,tiles=S.tiles){if(from===to)return [from];let q=[from],seen=new Set(q),prev=new Map;for(let i=0;i<q.length;i++){let p=q[i];for(let n of near(p)){if(seen.has(n)||!walkable(tiles[n]))continue;seen.add(n);prev.set(n,p);if(n===to){let path=[n];while(path[0]!==from)path.unshift(prev.get(path[0]));return path}q.push(n)}}return null}
function dist(a,b){let p=bfs(a,b);return p?p.length-1:Infinity}
function reachableWithin(origin,limit){let seen=new Set([origin]),q=[[origin,0]];for(let i=0;i<q.length;i++){let [p,d]=q[i];if(d>=limit)continue;for(let n of near(p))if(walkable(S.tiles[n])&&!seen.has(n)){seen.add(n);q.push([n,d+1])}}return seen}
function home(u){return S.rooms.find(r=>r.id===u.room)?.cells[0]??u.pos}
function center(r){return r.cells[0]}
function roomAt(p){return S.rooms.find(r=>r.cells.includes(p))}
function mieEntrance(cells){if(!cells?.length)return null;const footprint=new Set(cells),options=new Set;for(const cell of cells)for(const n of near(cell))if(!footprint.has(n)&&walkable(S.tiles[n])&&dist(ENTRY,n)<Infinity)options.add(n);return [...options].sort((a,b)=>dist(ENTRY,a)-dist(ENTRY,b)||a-b)[0]??null}
function mieRoomDistance(enemyPos,cells){return Math.min(...cells.map(p=>dist(enemyPos,p)))}
function mieLureExtra(lure,pos){const base=dist(lure.start,OFFICE),remaining=dist(pos,OFFICE);return Math.max(0,lure.steps-(Number.isFinite(base)&&Number.isFinite(remaining)?Math.max(0,base-remaining):0))}
function cancelMieLure(e){const lure=e.lure;if(!lure)return;const owner=S.units.find(u=>u.id===lure.owner),stat=residentStat(owner);if(stat){stat.lureFailures++;stat.lureExtraSteps+=mieLureExtra(lure,e.pos)}if(owner?.lureTargetId===e.id)owner.lureTargetId=null;e.lure=null}
function completeMieLure(e){const lure=e.lure;if(!lure||e.hp<=0||e.pos!==lure.door)return;const owner=S.units.find(u=>u.id===lure.owner);if(!owner||owner.hp<=0){cancelMieLure(e);return}const stat=residentStat(owner);if(stat){stat.lureSuccess++;stat.lureExtraSteps+=mieLureExtra(lure,e.pos)}e.lure=null;owner.lureTargetId=null;owner.lureFlashUntil=S.time+1;owner.act='誘導成功';const before=e.hp;damage(e,10,'resident_special',owner);if(stat)stat.lureDamage+=Math.min(before,10);sfx('lure_success');message(`ミエッパが自慢の部屋へ${ENEMIES[e.kind].name}を誘い込んだ！`)}
function beginMieLure(u){if(u.hp<=0||u.lureTargetId!=null||(u.lureReady||0)>S.time)return;const room=S.rooms.find(r=>r.id===u.room),door=mieEntrance(room?.cells);if(door==null)return;const choices=S.enemies.filter(e=>e.hp>0&&['y','g','d','k'].includes(e.kind)&&!e.lure&&!guideActive(e)&&e.pos!==door&&mieRoomDistance(e.pos,room.cells)<=4&&bfs(e.pos,door)).sort((a,b)=>mieRoomDistance(a.pos,room.cells)-mieRoomDistance(b.pos,room.cells)||a.id-b.id);const e=choices[0];if(!e)return;u.lureReady=S.time+12;u.lureTargetId=e.id;e.lure={owner:u.id,door,start:e.pos,until:S.time+5,steps:0};const st=residentStat(u);if(st){st.lureAttempts++;st.lureKinds[e.kind]=(st.lureKinds[e.kind]||0)+1}u.act='敵を誘導中';message(`ミエッパ「自慢の部屋を見ていって！」 ${ENEMIES[e.kind].name}を誘導中`)}
function updateMieLures(){for(const e of S.enemies){if(!e.lure)continue;const owner=S.units.find(u=>u.id===e.lure.owner);if(e.hp<=0||!owner||owner.hp<=0||S.time>e.lure.until+1e-8||guideActive(e)||!bfs(e.pos,e.lure.door))cancelMieLure(e)}}
function spend(n){if(S.money<n){sfx('ui_error');message(`管理費が足りません（必要：${n}）`);moguruSay('あれっ、お金が足りない……');return false}S.money-=n;return true}
function breakBedrock(p){
  if(S.phase!=='build'){sfx('ui_error');message('構築フェーズでのみ岩盤を破壊できます');return false}
  if(S.wave<5){sfx('ui_error');message('岩盤破壊は第6話で解放されます');return false}
  if(S.tiles[p]!=='bedrock'){sfx('ui_error');message('固定岩盤を選択してください');return false}
  if(p===ENTRY||p===OFFICE||roomAt(p)||S.equip[p]){sfx('ui_error');message('保護されたマスは破壊できません');return false}
  if(!spend(150))return false;
  S.tiles[p]='floor';sfx('bedrock_break');message('固定岩盤を破壊しました！ 管理費-150');
  return true;
}
function freeRoom(r){return !S.units.some(u=>u.room===r.id)}
function residentCount(kind,exceptRoomId=null){return S.units.filter(u=>u.kind===kind&&u.room!==exceptRoomId).length}
function equipCount(kind){return Object.values(S.equip).filter(e=>e.kind===kind).length}
function equipmentPlacementCheck(p,kind){const item=EQUIPMENT[kind];if(!item)return {ok:false,reason:'設備を選択してください'};if(S.phase!=='build')return {ok:false,reason:'構築フェーズで設置してください'};if(S.wave+1<item.unlock)return {ok:false,reason:`第${item.unlock}話で解放されます`};if(p===ENTRY||p===OFFICE)return {ok:false,reason:'入口・管理室には設置できません'};if(S.equip[p])return {ok:false,reason:'すでに設備が設置されています'};if(S.tiles[p]!=='floor'||(kind!=='lunchbox'&&roomAt(p)))return {ok:false,reason:kind==='lunchbox'?'通常の床か住人の部屋の空き床を選択してください':'通常の空き床に設置してください'};if(kind==='lunchbox'&&S.units.some(u=>u.pos===p))return {ok:false,reason:'住人がいるマスには設置できません'};if(equipCount(kind)>=item.limit)return {ok:false,reason:kind==='fake_sign'?'偽の案内看板は最大2個までです':`${item.name}は上限${item.limit}個です`};if(kind==='fake_sign'&&near(p).filter(n=>walkable(S.tiles[n])).length<3)return {ok:false,reason:'ここは通路の分岐ではありません'};if(S.money<item.cost)return {ok:false,reason:`管理費が足りません（必要：${item.cost}）`};return {ok:true,reason:`${item.name}／管理費${item.cost}`}}
function effectFootprint(p,kind){if(!walkable(S.tiles[p]))return new Set;const radius=kind==='noise'?6:kind==='lunchbox'?3:kind==='haunted_tv'?2:kind==='fake_sign'?0:0;return reachableWithin(p,radius)}
function miePreviewFootprint(cells){const door=mieEntrance(cells);if(door==null)return {door:null,range:new Set};const reachable=new Set;for(const cell of cells)if(walkable(S.tiles[cell]))for(const p of reachableWithin(cell,4))reachable.add(p);return {door,range:new Set([...reachable].filter(p=>dist(p,door)<Infinity))}}
function residentFootprints(p,kind){if(!walkable(S.tiles[p]))return {activity:new Set,search:new Set,attack:new Set,support:new Set,lure:new Set,lureDoor:null};const k=TYPES[kind],activityRadius=kind==='pak'?6:kind==='dos'?7:k.range,searchRadius=kind==='pak'?6:k.range,attackRadius=kind==='dos'?2:kind==='bibi'?0:1,supportRadius=kind==='bibi'?6:kind==='pika'?4:kind==='mie'?3:0,lure=kind==='mie'?miePreviewFootprint(roomCells(p,kind)||[]):{range:new Set,door:null};return {activity:reachableWithin(p,activityRadius),search:reachableWithin(p,searchRadius),attack:reachableWithin(p,attackRadius),support:reachableWithin(p,supportRadius),lure:lure.range,lureDoor:lure.door}}
let forecastCache={signature:null,result:null};
function forecastRoutes(){const signature=S.tiles.join(',');if(forecastCache.signature===signature)return forecastCache.result;const visits=new Map,choices=new Map,routes={};for(const kind of Object.keys(ENEMIES)){let pos=ENTRY,heading=1,nav={},trace=[pos],seen=new Set;for(let steps=0;steps<W*H*8&&pos!==OFFICE;steps++){const move=MazeAI.nextStep({from:pos,goal:OFFICE,kind,heading,nav,tiles:S.tiles,width:W,height:H,guided:false,leader:null});if(move.pos===pos)break;const branch=choices.get(pos)||new Set;branch.add(move.pos);choices.set(pos,branch);pos=move.pos;heading=move.heading;trace.push(pos);if(pos===OFFICE)break}routes[kind]=trace;for(const p of new Set(trace))visits.set(p,(visits.get(p)||0)+1)}forecastCache={signature,result:{visits,choices,routes}};return forecastCache.result}
function forecastSignRoute(p,dir){const routes={};const visits=new Set;for(const kind of ['y','g','d','k']){let pos=ENTRY,heading=1,nav={},used=false,trace=[pos];for(let steps=0;steps<W*H*8&&pos!==OFFICE;steps++){let next;if(pos===p&&!used){const n=pos+dirs[dir];if(near(pos).includes(n)&&walkable(S.tiles[n])){next=n;heading=dir;used=true;nav.stack=[pos]}}if(next==null){const move=MazeAI.nextStep({from:pos,goal:OFFICE,kind,heading,nav,tiles:S.tiles,width:W,height:H,guided:false,leader:null});next=move.pos;heading=move.heading}if(next===pos)break;pos=next;trace.push(pos);if(trace.length>W*H*8)break}routes[kind]=trace;if(used)for(const cell of trace)visits.add(cell)}return {routes,visits}}
const ROOM_SIZES=Object.fromEntries(Object.entries(TYPES).map(([kind,t])=>[kind,t.size]));
function roomCells(p,kind){let [w,h]=ROOM_SIZES[kind],[x,y]=xy(p);if(x+w>W||y+h>H)return null;let cells=[];for(let dy=0;dy<h;dy++)for(let dx=0;dx<w;dx++)cells.push(p+dy*W+dx);return cells}
function roomFits(r,kind){let expected=roomCells(r.cells[0],kind);return !!expected&&expected.length===r.cells.length&&expected.every(p=>r.cells.includes(p))}
function clearForRoom(cells){return !!cells&&cells.every(n=>S.tiles[n]==='floor'&&!roomAt(n))}
function placementCheck(p,kind,ignoreId=null){const k=TYPES[kind],[w,h]=k.size,cells=roomCells(p,kind);if(S.wave+1<k.unlock)return {ok:false,color:'red',reason:`第${k.unlock}話で解放`,cells:cells||[]};if(residentCount(kind,ignoreId)>=k.limit)return {ok:false,color:'red',reason:`${k.name}は配置済みです（${k.limit}人まで）。退去後に再配置できます。`,cells:cells||[]};if(!cells)return {ok:false,color:'red',reason:'マップ外にはみ出します',cells:[]};if(cells.some(n=>S.tiles[n]==='entry'||S.tiles[n]==='office'))return {ok:false,color:'red',reason:'入口・管理室には置けません',cells};if(cells.some(n=>S.tiles[n]==='bedrock'))return {ok:false,color:'red',reason:'掘れない岩盤があります',cells};let existing=roomAt(p);if(cells.some(n=>{let r=roomAt(n);return r&&r.id!==ignoreId&&!(r===existing&&freeRoom(r)&&roomFits(r,kind))})||cells.some(n=>Object.hasOwn(S.equip,n)))return {ok:false,color:'red',reason:'ほかの部屋・設備と重なります',cells};if(cells.some(n=>S.tiles[n]!=='floor'))return {ok:false,color:'yellow',reason:'必要な広さの空き床がありません',cells};if(S.money<k.cost&&ignoreId==null)return {ok:false,color:'yellow',reason:`管理費が不足しています（必要${k.cost}）`,cells};return {ok:true,color:'green',reason:`${k.name} ${w}×${h}／管理費${k.cost}`,cells}}
const SIGN_DIRECTIONS=['上','右','下','左'],SIGN_ARROWS=['↑','→','↓','←'];
function signDirectionOptions(p){return dirs.map((delta,dir)=>({dir,pos:p+delta})).filter(a=>near(p).includes(a.pos)&&walkable(S.tiles[a.pos]))}
function cancelSignPlacement(){pendingSign=null;hideModal();renderTools();render()}
function confirmSignDirection(dir){if(!pendingSign)return false;const p=pendingSign.pos;if(!equipmentPlacementCheck(p,'fake_sign').ok||!signDirectionOptions(p).some(a=>a.dir===dir)){message('誘導できる方向がありません');cancelSignPlacement();return false}pendingSign.dir=dir;renderTools();render();showModal('偽の案内看板・設置確認',`<p>選択中：偽の案内看板</p><p>誘導方向：<b>${SIGN_DIRECTIONS[dir]} ${SIGN_ARROWS[dir]}</b><br>設置費用：管理費40</p><p>対象：ヨシダ・ゲン・権田・ハンコ主任</p><p>ハカリさん・立花には効果がありません。</p><p>水色：通常の予想経路／オレンジ：誘導後の予想経路</p>`,[['設置を確定する',()=>{hideModal();if(pendingSign?.pos===p&&pendingSign.dir===dir)placeEquipment(p,'fake_sign',dir);pendingSign=null;renderTools();render()}],['キャンセル',cancelSignPlacement]]);return true}
function placeEquipment(p,kind,dir=null){const item=EQUIPMENT[kind],check=equipmentPlacementCheck(p,kind);if(!check.ok){sfx('ui_error');message(check.reason);return false}if(kind==='fake_sign'&&dir==null){pendingSign={pos:p,dir:null};sfx('ui_click');message('通れる方向の矢印を選んでください（未確定・管理費消費なし）');renderTools();render();return false}if(kind==='fake_sign'&&!signDirectionOptions(p).some(a=>a.dir===dir)){sfx('ui_error');message('誘導できる方向がありません');return false}if(!spend(item.cost))return false;S.equip[p]={id:S.nextId++,kind,cool:0,disabled:false,dir,enhancedUntil:0,paidCost:item.cost,everUsed:false,everDisabled:false};sfx('trap_place');message(`${item.name}を設置！${kind==='fake_sign'?` 誘導：${SIGN_ARROWS[dir]}`:''}`);return true}
function removeEquipment(p){if(S.phase!=='build'){sfx('ui_error');message('戦闘中は設備を撤去できません');return false}const eq=S.equip[p];if(!eq){sfx('ui_error');message('設備がありません');return false}const refund=!eq.disabled&&!eq.everUsed&&!eq.everDisabled&&Number.isFinite(eq.paidCost)&&eq.paidCost>0?eq.paidCost:0;delete S.equip[p];for(const enemy of S.enemies)if(enemy.signPending?.id===eq.id)enemy.signPending=null;if(pendingSign?.pos===p)pendingSign=null;S.money+=refund;sfx('trap_remove');message(`設備を撤去しました。管理費＋${refund}`);return true}
function retireResident(id){if(S.phase!=='build'){sfx('ui_error');message('戦闘中は退去できません');return false}const resident=S.units.find(u=>u.id===id);if(!resident)return false;const room=S.rooms.find(r=>r.id===resident.room);if(!room)return false;const refund=Number.isFinite(resident.paidCost)&&resident.paidCost>0?resident.paidCost:0;S.units=S.units.filter(u=>u.id!==id);S.rooms=S.rooms.filter(r=>r.id!==room.id);for(const c of room.cells)S.tiles[c]='floor';S.money+=refund;selectedResident=null;sfx('retire');message(`${TYPES[resident.kind].name}が退去しました。管理費＋${refund}`);renderTools();render();return true}
function doTile(p){selected=p;let tapped=S.units.find(u=>u.pos===p&&u.hp>0);selectedResident=tapped?.id??null;if(S.phase!=='build'||(tapped&&mode!=='move'&&mode!=='retire')){sfx('ui_click');render();return}let t=S.tiles[p],r=roomAt(p),eq=S.equip[p];
if(mode==='dig'){let [x,y]=xy(p);if(t==='bedrock'){sfx('ui_error');message('ここは硬い岩盤なので掘れません')}else if(t!=='wall'){sfx('ui_error');message('ここは掘削済みです')}else if(x===0||x===W-1||y===0||y===H-1){sfx('ui_error');message('外周は掘削できません')}else if(!near(p).some(n=>walkable(S.tiles[n]))){sfx('ui_error');message('既存の床に隣接する壁だけ掘れます')}else if(spend(5)){S.tiles[p]='floor';sfx('dig');message('土を掘りました！');moguruSay('よいしょ、よいしょ！');requestAnimationFrame(()=>playDigEffect(p))}}
else if(mode==='bedrock_break')breakBedrock(p);
else if(mode==='fill'){if(t!=='floor'){sfx('ui_error');message('通常の床だけ埋め戻せます（入口・管理室・岩盤は対象外）')}else if(r||eq||S.units.some(u=>u.pos===p)){sfx('ui_error');message('部屋・設備・住人がある床は埋め戻せません')}else{let wasConnected=!!bfs(ENTRY,OFFICE);S.tiles[p]='wall';if(wasConnected&&!bfs(ENTRY,OFFICE)){S.tiles[p]='floor';sfx('ui_error');message('入口から管理室への通路を遮断するため埋め戻せません')}else{S.money+=5;sfx('fill');message('土砂を回収！ 管理費+5（1マス埋め戻し）')}}}
else if(mode==='room'){let [x,y]=xy(p);let cells=[p,p+1,p+W,p+W+1];if(x>=W-1||y>=H-1||cells.some(n=>S.tiles[n]!=='floor'||roomAt(n))){sfx('ui_error');message('2×2の空いた床が必要です（左上を選択）')}else {S.rooms.push({id:S.nextId++,cells});sfx('room_register');message('新しい部屋を登録しました！');requestAnimationFrame(()=>chooseResidentForRoom(p))}}
else if(mode==='unroom'){if(!r){sfx('ui_error');message('登録された部屋を選んでください')}else if(!freeRoom(r)){sfx('ui_error');message('入居中の部屋は解除できません')}else{S.rooms=S.rooms.filter(a=>a!==r);sfx('room_unreg');message('部屋登録を解除しました')}}
else if(TYPES[mode]){let check=placementCheck(p,mode);if(!check.ok){sfx('ui_error');message(check.reason)}else if(S.units.length>=6){sfx('ui_error');message('最大6人まで入居できます')}else if(spend(TYPES[mode].cost)){if(!r){r={id:S.nextId++,cells:check.cells};S.rooms.push(r)}let k=TYPES[mode];S.units.push({id:S.nextId++,kind:mode,room:r.id,pos:center(r),hp:k.hp,paidCost:k.cost,act:'待機',clock:0,attack:0,moves:0,sleep:0,alarm:0,awake:0,active:0,hits:0,patrolDir:1,repairs:0});sfx('resident_place');message(`${k.name}の部屋ができました！ 入居完了！`)}}
else if(mode==='move'){if(r&&!freeRoom(r)&&!S.moveSource){let resident=S.units.find(u=>u.room===r.id),[w,h]=ROOM_SIZES[resident.kind];S.moveSource=resident.id;sfx('ui_click');message(`引っ越し先の${w}×${h}マスの空き床を選んでください`)}else if(S.moveSource){let u=S.units.find(u=>u.id===S.moveSource),kind=u?.kind,old=S.rooms.find(a=>a.id===u?.room);if(!u){S.moveSource=null;sfx('ui_error');message('引っ越す住人が見つかりません')}else{let check=placementCheck(p,kind,old?.id);if(!check.ok){sfx('ui_error');message(check.reason)}else if(r&&!freeRoom(r)&&r!==old){sfx('ui_error');message('入居中の部屋には引っ越せません')}else if(r&&!roomFits(r,kind)){sfx('ui_error');message('サイズが合いません')}else {if(!r){r={id:S.nextId++,cells:check.cells};S.rooms.push(r)}u.room=r.id;u.pos=center(r);if(old&&old!==r){S.rooms=S.rooms.filter(a=>a!==old)}S.moveSource=null;sfx('resident_move');message(`${TYPES[u.kind].name}が引っ越しました`)}}}else{sfx('ui_error');message('引っ越す住人の部屋を選んでください')}}
else if(mode==='retire'){let resident=r&&S.units.find(u=>u.room===r.id);if(!resident){sfx('ui_error');message('退去させる住人の部屋を選んでください')}else{sfx('ui_click');const refund=Number.isFinite(resident.paidCost)?resident.paidCost:0;showModal('住人の退去確認',`<p>${TYPES[resident.kind].name}を退去させますか？</p><p>入居費用${refund}を返還します。部屋は通常の床として残ります。</p>`,[['退去する',()=>{hideModal();retireResident(resident.id)}],['キャンセル',hideModal]])}}
else if(EQUIPMENT[mode])placeEquipment(p,mode);
else if(mode==='remove')removeEquipment(p);
else sfx('ui_click');
renderTools();render()}
function prepare(){for(let u of S.units){u.pos=home(u);u.hp=TYPES[u.kind].hp;u.attack=0;u.moves=0;u.sleep=0;u.alarm=0;u.alarmCooldownSeen=null;u.alarmOutsideSeen=[];u.alarmBuffUntil=0;u.awake=0;u.active=0;u.hits=0;u.targetId=null;u.wakeReason=null;u.wakeTarget=null;u.act=u.kind==='dos'?'睡眠':'待機';u.repairs=0;u.repairTarget=null;u.repairClock=0;u.enhanceTarget=null;u.enhanceClock=0;u.comboReady=0;u.lureReady=0;u.lureTargetId=null;u.lureFlashUntil=0;u.patrolDir=1;u.sporeCool=0;u.sporePlaceAt=0;u.showoff=false;u.restIdle=0;u.restHealClock=0;u.restFlashUntil=0;u.lastCombatAt=null}for(let e of Object.values(S.equip)){e.everDisabled ||= !!e.disabled;e.cool=0;e.disabled=false;e.pulseUntil=0;e.enhancedUntil=0;e.enhancedBy=null;e.usedBy=[]}S.destroyedEquip=[];S.repairedEquipIds=[];S.spores=[];S.enemies=[];S.queue=[];S.time=0;S.spawnAt=0;S.spawned=0;S.kills=0;S.earned=0;S.bonusEarned=0;S.progress=0;S.fallen=new Set;S.alarm=0;S.signals=[];S.fx=[]}
function addFx(kind,pos,duration){if(S.phase==='battle'&&Number.isInteger(pos))S.fx.push({kind,pos,start:S.time,duration})}
function playDigEffect(pos){if(S.phase!=='build'||S.tiles[pos]!=='floor')return;const tile=$('map').children[pos];if(!tile)return;const fx=document.createElement('span');fx.className='map-effect dig-effect';fx.innerHTML='<img src="assets/effects/effect_dig.png" alt="" onerror="this.style.display=\'none\'">';tile.append(fx);fx.addEventListener('animationend',()=>fx.remove(),{once:true})}
function start(){if(S.phase!=='build')return;if(!S.units.length){sfx('ui_error');message('まず住人を入居させてください');showModal('まだ侵攻を開始できません','<p>住人が配置されていません。「住まい」タブから住人を1人以上配置してください。</p>',[['確認',hideModal]]);return}if(!bfs(ENTRY,OFFICE)){sfx('ui_error');message('管理室まで通路が繋がっていません');showModal('まだ侵攻を開始できません','<p>入口から管理室まで通路がつながっていません。「掘る」タブで道をつなげてください。</p>',[['確認',hideModal]]);return}battleSnapshot=clone(S);prepare();initStats();S.phase='battle';S.paused=false;S.speed=1;S.queue=waveQueue(STAGE_DATA[S.wave]);checkpoint=checkpoint||clone({...S,phase:'build'});sfx('wave_start');bgm('battle');bgmPause(false);message(`第${S.wave+1}回の立ち退き業者が接近中！`);moguruSay('みんな、立ち退き業者が来ましたー！');renderTools();render()}
function markResidentCombat(u){if(!u||!TYPES[u.kind])return;if(u.restIdle>0){const st=residentStat(u);if(st)st.restStops++}u.lastCombatAt=S.time;u.restIdle=0;u.restHealClock=0}
function damage(v,n,source,attacker){if(v.hp<=0)return;if(source==='enemy')markResidentCombat(v);else if(['resident','combo','resident_special'].includes(source))markResidentCombat(attacker);const base=n;if(source==='resident'&&attacker?.alarmBuffUntil>S.time){n*=1.2;const st=residentStat(attacker),b=residentStat(S.units.find(u=>u.id===attacker.alarmSourceId));if(st)st.alarmBonus+=(n-base);if(b)b.alarmBonus+=(n-base)}let actual=Math.min(v.hp,n);v.hp=Math.max(0,v.hp-n);if(actual>0&&['enemy','resident','combo','resident_special','poison','trap'].includes(source))addFx('attack',v.pos,.26);
  if(actual>0){if(source==='enemy')sfx('attack_enemy');else if(source==='resident')sfx('attack_resident');else if(source==='combo')sfx('combo')}
  if(source==='enemy'){let st=residentStat(v);if(st)st.taken+=actual}
  else{let st=enemyStat(v);if(st)st.taken+=actual;if(['resident','combo','resident_special','poison'].includes(source)){let a=residentStat(attacker);if(a){a.dealt+=actual;if(source==='resident'){a.normalDamage+=actual;if(attacker?.kind==='mie'&&attacker.lureTargetId!=null)a.lureAttacks++}else if(source==='combo'){a.comboDamage+=actual;if(attacker?.kind==='mie'&&attacker.lureTargetId!=null)a.lureCombos++}else if(source==='poison')a.poisonDamage+=actual;else a.specialDamage+=actual}}else if(source==='trap'){let a=equipStat(attacker);if(a)a.dealt+=actual}}
  if(v.hp===0){if(source==='enemy'){S.fallen.add(v.id);let st=residentStat(v);if(st){st.fallen=true;if(v.kind==='pika'&&v.repairTarget!=null)st.repairInterrupts++}if(v.kind==='mie')for(const enemy of S.enemies)if(enemy.lure?.owner===v.id)cancelMieLure(enemy)}else{if(v.lure)cancelMieLure(v);S.kills++;sfx('enemy_defeat');let st=enemyStat(v);if(st)st.defeated=true;if(['resident','combo','resident_special','poison'].includes(source)){let a=residentStat(attacker);if(a){a.kills++;if(source==='poison')a.poisonKills++}}else if(source==='trap'){let a=equipStat(attacker);if(a)a.kills++}if(!v.rewarded){v.rewarded=true;let pay=ENEMIES[v.kind].reward;S.earned+=pay;S.money+=pay;if(st)st.reward=pay;message(`忘れ物回収！ +${pay}（${ENEMIES[v.kind].name}）`)}}}
  if(actual>0&&source!=='enemy'&&source!=='resident'&&source!=='combo')message(`${source==='trap'?EQUIPMENT[S.equip[attacker]?.kind]?.name||'罠':source==='poison'?'マヨイモの毒':TYPES[attacker?.kind]?.name||'住人'}：${fmt(actual)}ダメージ`);
  if(source==='resident'&&attacker?.kind!=='mie'&&v.hp>0){const mie=S.units.find(u=>u.kind==='mie'&&u.hp>0&&u.comboReady<=S.time&&isShowoff(u)&&dist(u.pos,v.pos)<=1&&dist(u.pos,attacker.pos)<=3&&activeAlly(attacker));if(mie){mie.comboReady=S.time+3;const st=residentStat(mie);if(st)st.combos++;damage(v,8,'combo',mie);addFx('alert',mie.pos,.3)}}
}
function enhancedAttack(eq,e,amount){if(!enhanced(eq)||!amount||e.hp<=0)return;const u=S.units.find(u=>u.id===eq.enhancedBy);if(!u)return;const before=e.hp;damage(e,amount,'resident_special',u);const st=residentStat(u);if(st)st.enhancedDamage+=Math.min(before,amount)}
function applyPoison(e,owner){if(e.hp<=0)return;const st=residentStat(S.units.find(u=>u.id===owner));if(st)st.poisonApplications++;if(e.poison&&e.poison.until>S.time){e.poison.until=S.time+3;return}e.poison={owner,until:S.time+3,nextTick:S.time+1}}
function tickPoison(e){const po=e.poison;if(!po||e.hp<=0)return;const owner=S.units.find(u=>u.id===po.owner);let guard=0;while(e.hp>0&&po.nextTick<=S.time+1e-8&&po.nextTick<=po.until+1e-8&&guard++<5){damage(e,2,'poison',owner);po.nextTick+=1}if(S.time>=po.until)e.poison=null}
const radius=(a,b,n=3)=>Math.abs(xy(a)[0]-xy(b)[0])+Math.abs(xy(a)[1]-xy(b)[1])<=n;
function activeAlly(u){return u.hp>0&&!(u.kind==='pak'&&u.sleep>0)&&!(u.kind==='dos'&&u.awake<=0&&u.active<=0)}
function isShowoff(u){return S.units.some(other=>other!==u&&activeAlly(other)&&dist(u.pos,other.pos)<=3)}
function enhanced(eq){return !!eq&&!eq.disabled&&eq.enhancedUntil>S.time}
function enhancedTrigger(eq){if(!enhanced(eq))return;const st=residentStat(S.units.find(u=>u.id===eq.enhancedBy));if(st)st.enhancedTriggers++}
function enhanceStep(u,dt){const current=Object.entries(S.equip).find(([,e])=>enhanced(e)&&e.enhancedBy===u.id);if(current){u.act='設備強化中';moveUnit(u,home(u),TYPES.pika.move);return}
  const eligible=Object.entries(S.equip).map(([p,e])=>({p:Number(p),e})).filter(({p,e})=>!e.disabled&&!enhanced(e)&&dist(home(u),p)<=4&&near(p).some(n=>walkable(S.tiles[n])&&dist(u.pos,n)<Infinity)).sort((a,b)=>dist(u.pos,a.p)-dist(u.pos,b.p)||a.p-b.p);
  const target=eligible[0];if(!target){u.enhanceTarget=null;u.enhanceClock=0;u.act='巡回中';moveUnit(u,home(u),TYPES.pika.move);return}
  if(u.enhanceTarget!==target.e.id){u.enhanceTarget=target.e.id;u.enhanceClock=0}
  const nearby=near(target.p).filter(n=>walkable(S.tiles[n])&&dist(u.pos,n)<Infinity).sort((a,b)=>dist(u.pos,a)-dist(u.pos,b)||a-b);
  if(!near(target.p).includes(u.pos)){u.act='設備強化へ移動中';moveUnit(u,nearby[0],TYPES.pika.move);return}
  u.act='設備を強化中';u.enhanceClock+=dt;if(u.enhanceClock>=3){target.e.enhancedUntil=S.time+15;target.e.enhancedBy=u.id;u.enhanceClock=0;u.enhanceTarget=null;let st=residentStat(u);if(st)st.enhances++;sfx('enhance');message(`ピカピカリが${EQUIPMENT[target.e.kind].name}を15秒間強化！`)}
}
function repairStep(u,dt){let st=residentStat(u),target=S.destroyedEquip?.find(t=>t.id===u.repairTarget),eligible=t=>!t.restored&&!S.repairedEquipIds.includes(t.id)&&dist(home(u),t.pos)<=6&&near(t.pos).some(n=>walkable(S.tiles[n])&&dist(u.pos,n)<Infinity);
  if(u.repairTarget!=null&&!target){u.repairTarget=null;u.repairClock=0;if(st)st.repairInterrupts++}
  if(!target&&u.repairs<2){target=S.destroyedEquip.filter(eligible).sort((a,b)=>dist(u.pos,a.pos)-dist(u.pos,b.pos)||a.id-b.id)[0];if(target){u.repairTarget=target.id;u.repairClock=0}}
  if(!target){enhanceStep(u,dt);return}
  const destinations=near(target.pos).filter(n=>walkable(S.tiles[n])&&dist(u.pos,n)<Infinity).sort((a,b)=>dist(u.pos,a)-dist(u.pos,b)||a-b);
  if(!destinations.length){u.repairTarget=null;u.repairClock=0;if(st)st.repairInterrupts++;u.act='巡回中';return}
  if(!near(target.pos).includes(u.pos)){u.act='修理対象へ移動中';moveUnit(u,destinations[0],TYPES.pika.move);return}
  u.act='修理中';u.repairClock+=dt;if(u.repairClock>=6){if(!S.equip[target.pos]){S.equip[target.pos]={id:target.id,kind:target.kind,cool:0,disabled:false,lunchboxWave:target.lunchboxWave,lunchboxUses:target.lunchboxUses||0};target.restored=true;S.repairedEquipIds.push(target.id);u.repairs++;if(st){st.repairs++;st.repairIds.push(target.id)}const deviceStat=equipStat(target.pos);if(deviceStat)deviceStat.repaired++;sfx('repair');message('ピカピカリが設備を修理しました！')}else if(st)st.repairInterrupts++;u.repairTarget=null;u.repairClock=0;u.act='修理完了'}
}
function patrolStep(u){if(u.moves>0)return;const allowed=reachableWithin(home(u),TYPES.mayo.range),d=u.patrolDir??1;for(const turn of [1,0,3,2]){let dir=(d+turn)%4,n=u.pos+dirs[dir];if(!near(u.pos).includes(n)||!walkable(S.tiles[n])||!allowed.has(n))continue;if(S.units.some(other=>other!==u&&other.hp>0&&other.pos===n))continue;const old=u.pos;u.patrolDir=dir;u.pos=n;u.moves=TYPES.mayo.move;let st=residentStat(u);if(st)st.patrolSteps++;S.spores??=[];if(S.time>=(u.sporePlaceAt||0)&&S.tiles[old]==='floor'&&!S.spores.some(sp=>sp.pos===old&&sp.until>S.time)){S.spores.push({pos:old,until:S.time+5,owner:u.id,hits:[]});u.sporePlaceAt=S.time+2;if(st){st.sporeTiles++;st.spores++}}u.act='巡回中';return}u.act='巡回待機'}
function supported(e,kind){return S.enemies.some(other=>other.hp>0&&other.kind===kind&&other.id!==e.id&&radius(e.pos,other.pos,3))}
function enemyBonuses(e){return {speed:supported(e,'h')?1.15:1,attack:supported(e,'k')?1.2:1,work:supported(e,'k')?1.2:1,chief:S.enemies.some(a=>a.hp>0&&a.kind==='t'&&a.rallyUntil>S.time&&radius(e.pos,a.pos,3))?1.1:1}}
function guideActive(e){return e.kind!=='h'&&S.enemies.some(a=>a.kind==='h'&&a.hp>0&&a.id!==e.id&&dist(e.pos,a.pos)<=3)}
function followLeader(e){return S.enemies.filter(a=>a.hp>0&&a.id!==e.id&&a.kind!=='k'&&dist(e.pos,a.pos)<=3).sort((a,b)=>dist(e.pos,a.pos)-dist(e.pos,b.pos)||a.id-b.id)[0]||null}
function effectiveSlow(e){return e.stickyUntil>S.time?.6:(e.slowUntil>S.time?.7:1)}
const GEN_DANGER=new Set(['spike','pitfall']);
function genDangerAt(p){const eq=S.equip[p];return !!eq&&!eq.disabled&&GEN_DANGER.has(eq.kind)}
function genSafePath(from){const tiles=S.tiles.map((t,p)=>genDangerAt(p)&&p!==from?'wall':t);return MazeAI.shortest(from,OFFICE,tiles,W,H)}
function genAvoid(e,next){if(e.kind!=='g'||!genDangerAt(next))return next;const eq=S.equip[next],stat=enemyStat(e);e.seenTrapIds??=[];if(!e.seenTrapIds.includes(eq.id)){e.seenTrapIds.push(eq.id);if(stat)stat.seenTraps++}const safe=genSafePath(e.pos);if(safe?.length>1&&safe[1]!==next){if(stat){stat.detours++;const direct=MazeAI.shortest(e.pos,OFFICE,S.tiles,W,H);stat.detourExtra+=Math.max(0,safe.length-(direct?.length||safe.length))}e.heading=dirs.indexOf(safe[1]-e.pos);e.nav.stack=[e.pos];return safe[1]}return next}
function redirectBySign(e,guided){if(guided||!['y','g','d','k'].includes(e.kind))return null;for(const [pStr,sign] of Object.entries(S.equip)){if(sign.kind!=='fake_sign'||sign.disabled)continue;const p=Number(pStr),range=enhanced(sign)?1:0;if(dist(e.pos,p)>range||(e.signUsed||[]).includes(sign.id))continue;const n=e.pos+dirs[sign.dir];if(!near(e.pos).includes(n)||!walkable(S.tiles[n]))continue;sign.everUsed=true;e.signUsed??=[];e.signUsed.push(sign.id);e.signPending={id:sign.id,pos:p,origin:e.pos};const before=dist(e.pos,OFFICE),after=dist(n,OFFICE);const extra=Number.isFinite(before)&&Number.isFinite(after)?Math.max(0,after-before+1):0;const stat=equipStat(p);if(stat){stat.redirects++;stat.uses++;stat.extraSteps+=extra}recordDeviceImpact(p,e);enhancedTrigger(sign);e.heading=sign.dir;e.nav??={};e.nav.stack=[e.pos];sfx('trap_sign');message(`${ENEMIES[e.kind].name}が偽の看板に誘導された！`);return n}return null}
function equipmentOnEnter(e,p){const eq=S.equip[p];if(eq&&!eq.disabled&&e.kind==='g'&&GEN_DANGER.has(eq.kind)){const st=enemyStat(e);if(st)st.immunePasses++;sfx('trap_evade');message('ゲンが危険な罠を見抜いて無傷で通過した')}else if(eq&&!eq.disabled&&eq.cool<=0){if(['spike','noise','sticky','pitfall'].includes(eq.kind))eq.everUsed=true;const stat=equipStat(p);if(['spike','noise','sticky','pitfall'].includes(eq.kind))recordDeviceImpact(p,e);if(eq.kind==='spike'){eq.cool=3;if(stat)stat.uses++;enhancedTrigger(eq);const normal=(e.kind==='t'?10:20)*(enhanced(eq)?1.25:1),bonus=e.kind==='d'?5:0,hpBefore=e.hp;if(stat){stat.spikeNormalDamage+=Math.min(hpBefore,normal);stat.spikeGondaBonus+=Math.min(Math.max(0,hpBefore-normal),bonus)}const st=enemyStat(e);if(e.kind==='d'&&st){st.gondaSpikeSteps++;st.gondaSpikeNormal+=Math.min(hpBefore,normal);st.gondaSpikeBonus+=Math.min(Math.max(0,hpBefore-normal),bonus)}sfx('trap_spike');damage(e,normal+bonus,'trap',p);message('トゲ罠が発動！')}
    else if(eq.kind==='noise'){eq.cool=3;eq.pulseUntil=S.time+.45;if(stat){stat.uses++;stat.specialTriggers++}sfx('trap_noise');const count=signal(p,6+(enhanced(eq)?1:0),'騒音装置');if(stat)stat.awakened+=count;enhancedTrigger(eq);for(const target of S.enemies.filter(v=>v.hp>0&&dist(p,v.pos)<=6)){if(target!==e)recordDeviceImpact(p,target);damage(target,5,'trap',p)}message('騒音装置が鳴り響いた！')}
    else if(eq.kind==='sticky'){eq.cool=5;e.stickyUntil=Math.max(e.stickyUntil||0,S.time+3+(enhanced(eq)?1:0));if(stat){stat.uses++;stat.specialTriggers++;if(!stat.slowedIds.includes(e.id))stat.slowedIds.push(e.id)}enhancedTrigger(eq);sfx('trap_sticky');damage(e,5,'trap',p);enhancedAttack(eq,e,3);message('ネバネバ床で業者が減速！')}
    else if(eq.kind==='pitfall'){const boosted=enhanced(eq),booster=S.units.find(u=>u.id===eq.enhancedBy);enhancedTrigger(eq);eq.disabled=true;e.freezeUntil=Math.max(e.freezeUntil||0,S.time+2+(boosted?1:0));if(stat){stat.uses++;stat.specialTriggers++;stat.stoppedTime+=2+(boosted?1:0)}sfx('trap_pitfall');damage(e,15,'trap',p);if(boosted&&booster&&e.hp>0){const before=e.hp;damage(e,8,'resident_special',booster);const a=residentStat(booster);if(a)a.enhancedDamage+=Math.min(before,8)}message('落とし穴！ 業者が足止めされた')}}
  for(const sp of S.spores||[])if(sp.pos===p&&sp.until>S.time&&!(sp.hits||[]).includes(e.id)){sp.hits??=[];sp.hits.push(e.id);e.slowUntil=Math.max(e.slowUntil||0,S.time+3);applyPoison(e,sp.owner);const st=residentStat(S.units.find(u=>u.id===sp.owner));if(st){st.sporeHits++;if(!st.slowedIds.includes(e.id))st.slowedIds.push(e.id)}}}
function equipmentTick(){for(const [pStr,eq] of Object.entries(S.equip)){if(eq.kind!=='haunted_tv'||eq.disabled||eq.cool>0)continue;const p=Number(pStr),target=S.enemies.filter(e=>e.hp>0&&!['h','t'].includes(e.kind)&&dist(e.pos,p)<=2&&(e.tvImmuneUntil||0)<=S.time).sort((a,b)=>dist(a.pos,p)-dist(b.pos,p)||a.id-b.id)[0];if(!target)continue;eq.everUsed=true;eq.cool=enhanced(eq)?9:12;target.tvImmuneUntil=S.time+6;const back=(target.heading+2)%4;let dest=target.pos;for(let i=0;i<2;i++){const n=dest+dirs[back];if(!near(dest).includes(n)||!walkable(S.tiles[n])){dest=target.pos;break}dest=n}const moved=dest!==target.pos;if(!moved){target.freezeUntil=Math.max(target.freezeUntil||0,S.time+1);message('おばけテレビ！ 業者が立ちすくんだ')}else{target.pos=dest;target.moves=Math.max(target.moves,0.2);target.nav??={};target.nav.stack=[dest];message('おばけテレビ！ 業者が2マス後退！')}sfx('trap_tv');const st=equipStat(p);if(st){st.uses++;st.specialTriggers++;if(moved&&!st.pushedIds.includes(target.id))st.pushedIds.push(target.id)}recordDeviceImpact(p,target);enhancedTrigger(eq);damage(target,10,'trap',p);enhancedAttack(eq,target,5)}}
function gondaDestroy(e,p,afterSpike=false){const target=S.equip[p];if(e.hp<=0||!target||target.disabled)return false;S.destroyedEquip??=[];S.destroyedEquip.push({id:target.id??`legacy-${p}`,pos:Number(p),kind:target.kind,lunchboxWave:target.lunchboxWave,lunchboxUses:target.lunchboxUses||0,restored:false});const deviceStat=equipStat(p);if(deviceStat)deviceStat.destroyed++;delete S.equip[p];const st=enemyStat(e);if(st){st.destroyed++;if(afterSpike)st.gondaSpikeBreaks++}sfx('equip_destroy');message(afterSpike?'権田がトゲ罠のダメージを受けてから破壊！':'権田が設備を破壊！');return true}
// Once per game-time step, each resident can receive at most one delivery.
function lunchboxTick(){if(S.phase!=='battle')return;const healedThisStep=new Set;
  for(const [pStr,box] of Object.entries(S.equip).sort((a,b)=>Number(a[0])-Number(b[0]))){
    if(box.kind!=='lunchbox'||box.disabled||box.cool>0)continue;
    if(box.lunchboxWave!==S.wave){box.lunchboxWave=S.wave;box.lunchboxUses=0}
    if((box.lunchboxUses||0)>=2)continue;
    const p=Number(pStr),candidates=S.units.filter(u=>u.hp>0&&u.hp<=TYPES[u.kind].hp*.5&&!healedThisStep.has(u.id)&&dist(p,u.pos)<=3).sort((a,b)=>a.hp/TYPES[a.kind].hp-b.hp/TYPES[b.kind].hp||a.id-b.id);
    const target=candidates[0];if(!target)continue;
    const boosted=enhanced(box),amount=boosted?30:20,before=target.hp;
    target.hp=Math.min(TYPES[target.kind].hp,target.hp+amount);
    const actual=target.hp-before;if(actual<=0)continue;
    healedThisStep.add(target.id);box.lunchboxUses++;box.cool=10;box.everUsed=true;
    const st=equipStat(p);if(st){st.uses++;st.heals++;st.healedHp+=actual;st.specialTriggers++;if(boosted)st.enhancedHeals++;if(!st.healedIds.includes(target.id))st.healedIds.push(target.id);if(box.lunchboxUses>=2)st.depleted=true}
    if(boosted)enhancedTrigger(box);
    sfx('heal');
    message(boosted?`ピカピカリの強化差し入れ！ ${TYPES[target.kind].name}のHPが${actual}回復！`:`大家さんの差し入れ！ ${TYPES[target.kind].name}のHPが${actual}回復！`);
    if(box.lunchboxUses>=2)message('大家さんの差し入れ箱：残り0回');
  }
}
function nextEnemyMove(e){const pending=e.signPending;if(pending){const sign=S.equip[pending.pos];if(!sign||sign.disabled||sign.id!==pending.id)e.signPending=null;else if(e.pos!==pending.origin&&e.pos!==pending.pos&&near(e.pos).filter(p=>walkable(S.tiles[p])).length>=3){e.signPending=null;const st=equipStat(pending.pos);if(st)st.specialTriggers++;damage(e,8,'trap',pending.pos);if(e.hp<=0)return e.pos}}
  const guided=guideActive(e);if(guided!==e.guided){e.guided=guided;if(e.kind!=='h'&&S.time-(e.lastGuideLog??-100)>=3){message(guided?`ハカリさんが${ENEMIES[e.kind].name}を案内中！`:`${ENEMIES[e.kind].name}への経路案内が解除されました`);e.lastGuideLog=S.time}}
  const sign=redirectBySign(e,guided);if(sign!=null){if(e.lure)cancelMieLure(e);return sign}
  if(e.lure&&!guided){const route=bfs(e.pos,e.lure.door);if(route?.length>1){const next=route[1];e.heading=dirs.indexOf(next-e.pos);return next}if(e.pos===e.lure.door){completeMieLure(e);return e.pos}cancelMieLure(e)}
  const leader=e.kind==='k'&&!guided?followLeader(e):null;
  const decision=MazeAI.nextStep({from:e.pos,goal:OFFICE,kind:e.kind,heading:e.heading??1,nav:e.nav??(e.nav={}),tiles:S.tiles,width:W,height:H,guided,leader});
  if(decision.pos!==e.pos){if(decision.deadEnd&&e.kind==='g'&&S.time-(e.nav.lastDeadLog??-100)>4){message('ゲンが行き止まりを記憶した');e.nav.lastDeadLog=S.time}if(e.kind==='y'&&decision.turn===1&&S.time-(e.nav.lastTurnLog??-100)>4){message('ヨシダが分岐で右折した');e.nav.lastTurnLog=S.time}e.heading=decision.heading}
  return genAvoid(e,decision.pos)}
