function naturalRestTick(dt){if(S.phase!=='battle')return;for(const u of S.units){const room=S.rooms.find(r=>r.id===u.room),safe=u.hp>0&&room?.cells.includes(u.pos)&&!S.enemies.some(e=>e.hp>0&&dist(e.pos,u.pos)<=1);if(!safe){if((u.restIdle||0)>0){const st=residentStat(u);if(st)st.restStops++}u.restIdle=0;u.restHealClock=0;continue}u.restIdle=(u.restIdle||0)+dt;if(u.restIdle<3-1e-8)continue;const st=residentStat(u);if(st)st.restSeconds+=dt;if(u.hp>=TYPES[u.kind].hp){u.restHealClock=0;continue}u.restHealClock=(u.restHealClock||0)+dt;while(u.restHealClock>=2-1e-8&&u.hp<TYPES[u.kind].hp){u.restHealClock-=2;const before=u.hp;u.hp=Math.min(TYPES[u.kind].hp,u.hp+1);if(u.hp>before){u.restFlashUntil=S.time+.8;if(st){st.naturalHeals++;st.naturalHealedHp+=u.hp-before}}}}}
